head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16609";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16609.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_27_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2'); } }, { id: "c_when_28_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_when_29_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }, { id: "c_when_35_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2'); } }, { id: "c_when_36_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_when_37_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }, { id: "c_when_43_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2'); } }, { id: "c_when_44_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_when_45_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }, { id: "c_when_78_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("dplmIsuTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.dplmIsuTpCd"); })()) === ''); } }, { id: "c_otherwise_79", fn: function(){ return (!(((dma_comSprtSvcApplVO.get("dplmIsuTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.dplmIsuTpCd"); })()) === ''))); } }, { id: "c_when_49", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "tr_57", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "tr_65", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_otherwise_82", fn: function(){ return (!(((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'))); } }, { id: "btn_fnPrint", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2' || (dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_5_onsubmit
 * @description form_5 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_5_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16609.form_5_onsubmit' }); }
};

/**
 * @method
 * @name btn_fnReport_onclick
 * @description 「발급」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnReport_onclick = async function(e){
    try {
        await scwin.fnReport('' + dma_comSprtSvcApplVO.get("dplmIsuTpCd") + '',(String(((dma_comSprtSvcApplVO.get("chrgNm[(i-1)]") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.chrgNm[(i-1)]"); })())) == null ? '' : ((dma_comSprtSvcApplVO.get("chrgNm[(i-1)]") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.chrgNm[(i-1)]"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_comSprtSvcApplVO.get("chrgNm[(i-1)]") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.chrgNm[(i-1)]"); })())) == null ? '' : ((dma_comSprtSvcApplVO.get("chrgNm[(i-1)]") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.chrgNm[(i-1)]"); })())))));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16609.btn_fnReport_onclick' }); }
};

/**
 * @method
 * @name btn_fnPrint_onclick
 * @description 「인쇄」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnPrint_onclick = function(e){
    try {
        scwin.fnPrint()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16609.btn_fnPrint_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearch_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearch_onclick = async function(e){
    try {
        await scwin.fnSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16609.btn_fnSearch_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch
 * @description fn Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch = async function () {
    const sbmOptions = {
        id: "tx_fnSearch",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnSearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fnReport
 * @description fn Report 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnReport = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_fnReportReq") ? $c.util.getComponent("dma_fnReportReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    $c.util.getComponent('ipt_method').setValue("comSprtSvcRsltInqList");
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    const nr = await scwin.tx_fnSearch();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil16607/jldfil16607.xml", { "method": "comSprtSvcRsltInqList" });
    }
};

/**
 * @method
 * @name fnReport
 * @description fn Report 처리
 * @param {String} dplmIsuTpCd dplmIsuTpCd
 * @param {String} chrgNm chrgNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnReport = async function (dplmIsuTpCd, chrgNm) {
    if (dplmIsuTpCd === "1") {
        $c.util.getComponent('ipt_nTempleteCd').setValue("RLDFIL00046");
    } else {
        if (dplmIsuTpCd === "2") {
            $c.util.getComponent('ipt_nTempleteCd').setValue("RLDFIL00047");
        } else {
            await $c.win.alert("잘못된 교육구분코드 입니다.\n관리자에게 문의하세요.");
            return;
        }
    }
    $c.util.getComponent('ipt_eduCompltprnNm').setValue(chrgNm);
    await scwin.tx_fnReport();
};

/**
 * @method
 * @name fnPrint
 * @description fn Print 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnPrint = function () {
    const comSprtSvcPrint = '/jldfil16613/jldfil16613.xml';
    const optionCom = "scrollbars=yes,resizable=yes,toolbar=no,menubar=yes,width=820,height=350";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    (Promise.resolve($c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(comSprtSvcPrint), String((typeof optionCom !== 'undefined' ? optionCom : '') || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, '' ? Object.assign({ id: "comSprtSvcPrint", scrollbars: true, resizable: true, width: "820", height: "350", type: "pageFramePopup" }, { id: '' }) : { id: "comSprtSvcPrint", scrollbars: true, resizable: true, width: "820", height: "350", type: "pageFramePopup" }), {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("comSprtSvcPrint"); this.closed = true; } });
};
